/* Platform operations demo. Server authentication and tenant isolation are not implemented. */
const ADMIN_MENU=[['overview','grid','Ерөнхий самбар'],['listings','apartment','Зарын хяналт'],['brokers','briefcase','Зуучлагчид'],['members','users','Хэрэглэгчид'],['ads','megaphone','Зар сурталчилгаа'],['reports','shield','Мэдээлсэн зарууд'],['support','message','Хэрэглэгчийн тусламж'],['content','file-text','Мэдээ ба нийтлэл'],['analytics','chart','Тайлан'],['settings','settings','Үйлчилгээний тохиргоо'],['audit','book-open','Үйлдлийн түүх']];
const ADMIN_LABELS={approved:'Баталсан',pending:'Хянаж байна',rejected:'Татгалзсан',suspended:'Түр зогсоосон',active:'Идэвхтэй',paused:'Түр зогсоосон',expired:'Хугацаа дууссан',scheduled:'Эхлэхийг хүлээж байна',draft:'Ноорог',requested:'Шинэ хүсэлт',new:'Шинэ',progress:'Шалгаж байна',resolved:'Шийдвэрлэсэн',dismissed:'Хаасан',published:'Нийтэлсэн',archived:'Архивласан',hidden:'Нуусан'};
let adminQuery='',adminFilter='all',adminPageNumber=0,adminSelected=new Set(),adminContentTab='notices';
function adminState(){if(!flowState.admin||typeof flowState.admin!=='object'||Array.isArray(flowState.admin))flowState.admin={};const a=flowState.admin;for(const key of ['listingReviews','brokerReviews','memberMeta','noticeOverrides'])if(!a[key]||typeof a[key]!=='object'||Array.isArray(a[key]))a[key]={};for(const key of ['members','notices','audit','brokerHistory'])if(!Array.isArray(a[key]))a[key]=[];a.settings={reviewListings:false,reviewBrokerListings:false,...a.settings};return a}
function adminBadge(status){return `<span class="admin-badge is-${esc(status)}"><i></i>${esc(ADMIN_LABELS[status]||status)}</span>`}
function adminReview(h){const item=adminState().listingReviews[h.id];if(item?.status==='suspended')return 'suspended';if(h.moderationStatus==='pending'&&item?.version!==h.updatedAt)return 'pending';return item?.status||h.moderationStatus||'approved'}
function adminBrokerId(h){return h.brokerId||(h.proManaged||h.contactRole==='agent'?'broker-local':'')}
function adminCanPublish(h){if(adminReview(h)!=='approved')return false;const id=adminBrokerId(h);return !id||brokerEligible(id)}
function adminPrepareListing(h){h.moderationStatus=adminState().settings.reviewListings||!!adminBrokerId(h)?'pending':'approved';return officeBindListing(h)}
function adminCampaignSaved(record,old){if(record.stage==='requested'){record.adminStatus='pending';record.adminReason='';record.submittedAt=new Date().toISOString()}else{record.adminStatus='draft';record.adminReason=''}return record}
function adminAdState(c){if(c.stage!=='requested')return 'draft';if(!c.adminStatus||c.adminStatus==='pending')return 'pending';if(c.adminStatus!=='approved')return c.adminStatus;if(c.endDate<proToday())return 'expired';if(c.startDate>proToday())return 'scheduled';return 'active'}
function adminPromotion(h){if(!isPublicListing(h))return null;return proState().campaigns.find(c=>brokerEligible(c.brokerId||'broker-local')&&adminAdState(c)==='active'&&(c.listingIds||[]).includes(h.id)&&(!c.area||c.area===h.area))||null}
function adminPromotionBadge(h){return adminPromotion(h)?'<span class="admin-sponsored">'+icon('sparkles')+'Онцлох зар · Демо</span>':''}
function adminProListingStatus(h){const review=adminState().listingReviews[h.id],broker=adminState().brokerReviews[adminBrokerId(h)];return `<div class="pro-admin-decision"><span>Платформын хяналт</span>${adminBadge(adminReview(h))}${review?.reason?'<p>'+esc(review.reason)+'</p>':''}${adminBrokerId(h)&&!brokerEligible(adminBrokerId(h))?'<p>Байгууллагын хяналт: '+esc(ADMIN_LABELS[brokerStatus(adminBrokerId(h))])+'</p>':''}${['suspended','rejected'].includes(broker?.status)?'<p>Байгууллагын хяналт: '+esc(ADMIN_LABELS[broker.status])+'</p>':''}</div>`}
function adminProCampaignStatus(c){return `<div class="pro-admin-decision"><span>Админы шийдвэр</span>${adminBadge(adminAdState(c))}${c.adminReason?'<p>'+esc(c.adminReason)+'</p>':''}<p>${adminAdState(c)==='active'?'Нийтэд харагдах холбоотой зарууд онцлох хэсэгт орно.':'Хүсэлт, хугацаа болон зарын хяналтаас шалтгаалан онцлох төлөв өөрчлөгдөнө.'}</p></div>`}
function adminPromotedHomes(){return homes.filter(h=>adminPromotion(h))}
function adminPromotedSection(){const list=adminPromotedHomes();return list.length?`<section class="wrap admin-promoted-section"><div class="section-head"><h2>${icon('sparkles')}Онцлох зарууд</h2><span>Баталсан сурталчилгаа · Демо</span></div><div class="cards">${list.slice(0,4).map(card).join('')}</div></section>`:''}
function adminLog(action,target,before,after,reason=''){adminState().audit.unshift({id:flowId(),date:new Date().toISOString(),actor:'Демо админ',action,target:String(target),before:String(before||'—'),after:String(after||'—'),reason});adminState().audit=adminState().audit.slice(0,2000)}
function adminCommit(action,target,mutate,before='',after='',reason='',actor='Демо админ'){const snapshot=JSON.stringify(flowState);mutate();adminLog(action,target,before,after,reason);adminState().audit[0].actor=actor;if(!persistFlows()){Object.assign(flowState,JSON.parse(snapshot));return false}closeOverlay();adminSelected.clear();render();toast('Шийдвэр хадгалагдлаа · Демо орчин');return true}
function adminHeading(kicker,title,copy,actions=''){return `<div class="admin-heading"><div><span>${kicker}</span><h1>${title}</h1><p>${copy}</p></div><div class="admin-heading-actions">${actions}</div></div>`}
function adminMetric(title,value,glyph,note,url){return `<a class="admin-metric" href="#/admin/${url}"><div><span>${title}</span><i>${icon(glyph)}</i></div><strong>${value}</strong><p>${note}</p></a>`}
function adminEmpty(title,copy){return `<div class="admin-empty">${icon('folder')}<h3>${title}</h3><p>${copy}</p></div>`}
function adminTitle(tab){return ADMIN_MENU.find(m=>m[0]===tab)?.[2]||'Ерөнхий самбар'}
function adminPage(tab='overview'){adminState();if(!ADMIN_MENU.some(m=>m[0]===tab))tab='overview';const count=homes.filter(h=>adminReview(h)==='pending').length;const page=tab==='overview'?adminOverview():tab==='listings'?adminListings():tab==='brokers'?adminBrokers():tab==='members'?adminMembers():tab==='ads'?adminAds():tab==='reports'?adminTickets('reports'):tab==='support'?adminTickets('support'):tab==='content'?adminContent():tab==='analytics'?adminAnalytics():tab==='settings'?adminSettings():adminAudit();return `<div class="admin-shell"><aside class="admin-sidebar"><a class="admin-brand" href="#/admin"><img src="assets/oroo.png" alt="Өрөө"><span>ADMIN</span></a><div class="admin-workspace">${icon('shield')}<div><b>Платформын удирдлага</b><span>Демо администратор</span></div></div><small class="admin-nav-title">ҮЙЛ АЖИЛЛАГАА</small><nav class="admin-menu" aria-label="Админ цэс">${ADMIN_MENU.map(([key,glyph,label])=>`<a href="#/admin/${key}" onclick="adminResetView()" ${key===tab?'aria-current="page"':''}>${icon(glyph)}<span>${label}</span>${key==='listings'&&count?'<b>'+count+'</b>':''}</a>`).join('')}</nav><div class="admin-sidebar-bottom"><a href="#/pro">${icon('briefcase')}Өрөө PRO ${icon('arrow-up-right')}</a><a href="#/">${icon('external-link')}Хэрэглэгчийн сайт</a><p><i></i>Локал демо · Серверт холбогдоогүй</p></div></aside><button class="admin-menu-shade" aria-label="Админ цэс хаах" onclick="document.querySelector('.admin-shell').classList.remove('menu-open')"></button><div class="admin-work"><header class="admin-header"><button class="admin-mobile-menu" aria-label="Админ цэс нээх" onclick="document.querySelector('.admin-shell').classList.toggle('menu-open')">${icon('menu')}</button><div><span>ӨРӨӨ ADMIN</span><b>${adminTitle(tab)}</b></div><div class="admin-header-right"><span class="admin-environment"><i></i>Демо орчин</span><span class="admin-date">${proToday()}</span><a href="#/admin/audit" aria-label="Үйлдлийн түүх">${icon('bell')}</a><span class="admin-avatar">A</span></div></header><div class="admin-content">${page}<footer class="admin-footer"><b>Өрөө ADMIN</b><span>Зөвхөн энэ браузерын мэдээлэл · Серверийн нэвтрэлт, эрхийн хамгаалалт холбогдоогүй.</span></footer></div></div></div>`}
function adminResetView(){adminQuery='';adminFilter='all';adminPageNumber=0;adminSelected.clear()}
function adminToolbar(placeholder,options=[]){return `<form class="admin-toolbar" onsubmit="event.preventDefault();adminQuery=this.elements.q.value.trim();adminPageNumber=0;adminSelected.clear();render()"><div class="admin-search">${icon('search')}<input name="q" value="${esc(adminQuery)}" placeholder="${placeholder}" aria-label="Админ хайлт"><button>Хайх</button></div>${options.length?`<select aria-label="Төлөвөөр шүүх" onchange="adminFilter=this.value;adminPageNumber=0;adminSelected.clear();render()"><option value="all">Бүх төлөв</option>${options.map(s=>`<option value="${s}" ${adminFilter===s?'selected':''}>${ADMIN_LABELS[s]}</option>`).join('')}</select>`:''}<button type="button" aria-label="Хайлт цэвэрлэх" onclick="adminResetView();render()">${icon('refresh')}</button></form>`}
function adminMatches(record,status){return (adminFilter==='all'||adminFilter===status)&&(!adminQuery||JSON.stringify(record).toLowerCase().includes(adminQuery.toLowerCase()))}
function adminPaginate(items){adminPageNumber=Math.max(0,Math.min(adminPageNumber,Math.max(0,Math.ceil(items.length/10)-1)));return items.slice(adminPageNumber*10,adminPageNumber*10+10)}
function adminPagination(total){return `<div class="admin-pagination"><span>${total?adminPageNumber*10+1:0}–${Math.min(total,adminPageNumber*10+10)} / ${total} бүртгэл</span><div><button aria-label="Өмнөх хуудас" ${adminPageNumber===0?'disabled':''} onclick="adminPageNumber--;adminSelected.clear();render()">${icon('chevron-left')}</button><b>${adminPageNumber+1}</b><button aria-label="Дараах хуудас" ${(adminPageNumber+1)*10>=total?'disabled':''} onclick="adminPageNumber++;adminSelected.clear();render()">${icon('chevron-right')}</button></div></div>`}
function adminOverview(){const a=adminState(),pending=homes.filter(h=>adminReview(h)==='pending'),ads=proState().campaigns.filter(c=>adminAdState(c)==='pending'),reports=flowState.reports.filter(r=>!['resolved','dismissed'].includes(r.adminStatus)),support=adminSupportRequests().filter(r=>r.adminStatus!=='resolved');return `${adminHeading('ПЛАТФОРМЫН ӨНӨӨДӨР','Итгэлтэй платформыг хамт бүтээе.','Зар, зуучлагч, сурталчилгаа болон хэрэглэгчийн хүсэлтийг нэг дороос.',`<button onclick="adminSeedExamples()">${icon('sparkles')}Жишээ ажлын урсгал</button><a class="admin-primary" href="#/admin/listings">${icon('shield')}Хяналтаа эхлүүлэх</a>`)}<div class="admin-overview-banner"><div><span>ӨРӨӨ · ҮЙЛ АЖИЛЛАГААНЫ ТӨВ</span><h2>Зөв мэдээлэл.<br>Илүү найдвартай орон зай.</h2><p>Хэрэглэгчийн сайт ↔ Өрөө PRO ↔ Удирдлага</p><a href="#/admin/settings">${icon('settings')}Хяналтын горим тохируулах ${icon('arrow-right')}</a></div><div class="admin-banner-art" aria-hidden="true">${icon('shield')}<i>${icon('check')}</i><b>${icon('apartment')}</b></div></div><div class="admin-metrics">${adminMetric('Нийт зар',homes.length,'apartment',homes.filter(isPublicListing).length+' нийтэд харагдаж байна','listings')}${adminMetric('Хүлээгдэж буй хяналт',pending.length,'shield','Шалгаж батлах зарууд','listings')}${adminMetric('Шинэ сурталчилгаа',ads.length,'megaphone','Зуучлагчийн хүсэлт','ads')}${adminMetric('Мэдээлэл ба тусламж',reports.length+support.length,'message',reports.length+' мэдээлэл · '+support.length+' хүсэлт','support')}</div><div class="admin-dashboard-grid"><section class="admin-panel"><div class="admin-panel-head"><div><h2>Анхаарал шаардсан ажлууд</h2><p>Хүлээгдэж буй ажлын дараалал</p></div><span class="admin-live">Шууд бүртгэл</span></div>${[['listings','shield','Зарын хяналт',pending.length,'Зураг, үнэ, байршил болон мэдээллийг шалгах'],['ads','megaphone','Сурталчилгааны хүсэлт',ads.length,'Зуучлагчийн хүсэлтийг шалгаж, хугацааг батлах'],['reports','flag','Мэдээлсэн зар',reports.length,'Хэрэглэгчийн мэдээллийг шалгаж шийдвэрлэх'],['support','message','Хэрэглэгчийн тусламж',support.length,'Хариу хүлээж буй үйлчилгээний хүсэлт']].map(([url,glyph,title,count,copy])=>`<a class="admin-queue" href="#/admin/${url}"><i>${icon(glyph)}</i><div><b>${title}</b><p>${copy}</p></div><strong>${count}</strong>${icon('chevron-right')}</a>`).join('')}</section><section class="admin-panel"><div class="admin-panel-head"><div><h2>Платформын бүтэц</h2><p>Энэ браузерт байгаа мэдээлэл</p></div>${icon('chart')}</div><div class="admin-ring" style="--share:${homes.length?homes.filter(isPublicListing).length/homes.length*100:0}%"><div><b>${homes.filter(isPublicListing).length}</b><span>Нийтэд харагдах зар</span></div></div><div class="admin-legend">${[['Нийтэд харагдаж байна',homes.filter(isPublicListing).length],['Хянаж байна',pending.length],['Бусад төлөв',homes.filter(h=>!isPublicListing(h)&&adminReview(h)!=='pending').length]].map(([name,count])=>`<p><i></i>${name}<b>${count}</b></p>`).join('')}</div></section><section class="admin-panel"><div class="admin-panel-head"><h2>Сүүлийн үйлдлүүд</h2><a href="#/admin/audit">Бүгд ${icon('arrow-right')}</a></div>${a.audit.length?a.audit.slice(0,5).map(row=>`<div class="admin-activity"><i>${icon('check')}</i><div><b>${esc(row.action)}</b><p>${esc(row.target)} · ${esc(row.reason||row.after)}</p></div><time>${esc(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Ulaanbaatar',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(row.date)))}</time></div>`).join(''):adminEmpty('Хяналтын түүх эхлээгүй','Хадгалсан шийдвэр бүр энд бүртгэгдэнэ.')}</section><section class="admin-panel admin-policy-card"><span>ХЯНАЛТЫН ТОХИРГОО</span><h2>Таны нийтлэх дүрэм</h2><p>Шинэ зар: <b>${a.settings.reviewListings?'Батлах шаардлагатай':'Шууд нийтлэх'}</b></p><p>PRO зар: <b>${'Батлах шаардлагатай'}</b></p><p>Сурталчилгаа: <b>Админ баталсны дараа</b></p><a href="#/admin/settings">Дүрэм өөрчлөх ${icon('arrow-right')}</a><small>Хуучин заруудыг автоматаар өөрчлөхгүй.</small></section></div>`}
function adminListingRows(){const priority={pending:0,suspended:1,rejected:2,approved:3};return homes.filter(h=>adminMatches(h,adminReview(h))).sort((a,b)=>priority[adminReview(a)]-priority[adminReview(b)]||b.id-a.id)}
function adminListings(){const all=adminListingRows(),list=adminPaginate(all);return `${adminHeading('ЗАР БА МЭДЭЭЛЛИЙН ЧАНАР','Зарын хяналт','Хяналтын шийдвэр нь хэрэглэгчийн хайлт, газрын зураг болон PRO-д зэрэг үйлчилнэ.')}<div class="admin-inline-summary">${['approved','pending','rejected','suspended'].map(s=>`<button onclick="adminFilter='${s}';adminPageNumber=0;adminSelected.clear();render()">${adminBadge(s)}<b>${homes.filter(h=>adminReview(h)===s).length}</b></button>`).join('')}</div>${adminToolbar('Зарын дугаар, нэр, дүүрэг, зуучлагч',['pending','approved','rejected','suspended'])}<div class="admin-panel admin-table-panel"><div class="admin-table-top"><b>${all.length} зар</b><div><span>${adminSelected.size} сонгосон</span><button ${adminSelected.size?'':'disabled'} onclick="adminOpenReview(Array.from(adminSelected))">${icon('shield')}Сонгосон зар шалгах</button></div></div><div class="admin-table-scroll"><table class="admin-table"><thead><tr><th><input type="checkbox" aria-label="Энэ хуудасны заруудыг сонгох" ${list.length&&list.every(h=>adminSelected.has(h.id))?'checked':''} onchange="adminSelectPage(this.checked)"></th><th>Зар / Байршил</th><th>Үнэ</th><th>Оруулсан</th><th>Хяналт</th><th>Нийтэд</th><th></th></tr></thead><tbody>${list.map(h=>`<tr><td><input type="checkbox" aria-label="${esc(h.name)} сонгох" ${adminSelected.has(h.id)?'checked':''} onchange="this.checked?adminSelected.add(${h.id}):adminSelected.delete(${h.id});render()"></td><td><div class="admin-property"><img src="${imageFor(h)}" alt="Зарын зураг"><div><b>${esc(h.name)}</b><p>№ ${h.id} · ${esc(h.area)}</p><span>${h.size||'—'} м² · ${types[h.type]}</span></div></div></td><td class="admin-price">${propertyPriceMarkup(h)}</td><td>${h.proManaged?'Өрөө PRO':h.local?'Хэрэглэгч':'Жишээ өгөгдөл'}<small>${esc(h.agencyName||h.contactName||'')}</small></td><td>${adminBadge(adminReview(h))}</td><td><span class="admin-visibility ${isPublicListing(h)?'visible':''}">${isPublicListing(h)?'Харагдана':'Харагдахгүй'}</span></td><td><button onclick="adminOpenReview([${h.id}])">Шалгах ${icon('chevron-right')}</button></td></tr>`).join('')}</tbody></table></div>${!all.length?adminEmpty('Зар олдсонгүй','Хайлт эсвэл төлөвөө өөрчилнө үү.'):''}${adminPagination(all.length)}</div>`}
function adminSelectPage(checked){adminPaginate(adminListingRows()).forEach(h=>checked?adminSelected.add(h.id):adminSelected.delete(h.id));render()}
function adminOpenReview(ids){ids=ids.map(Number).filter(id=>homes.some(h=>h.id===id));if(!ids.length)return;const h=homes.find(h=>h.id===ids[0]);modal(`<div class="admin-modal-heading"><span>ЗАРЫН ХЯНАЛТ</span><h2>${ids.length===1?esc(h.name):ids.length+' зарын шийдвэр'}</h2><p>Шийдвэр, тайлбар PRO болон хэрэглэгчийн харагдацад үйлчилнэ.</p></div>${ids.length===1?`<div class="admin-review-property"><img src="${imageFor(h)}" alt="Хянах зар"><div><b>№ ${h.id}</b><h3>${propertyPriceMarkup(h)}</h3><p>${esc(listingAddress(h))}</p>${adminBadge(adminReview(h))}</div></div><details class="admin-review-details"><summary>Зарын дэлгэрэнгүй мэдээлэл</summary>${listingInfoRows(h)}${listingEquipment(h)}<p>${esc(h.description||h.desc||'')}</p><div class="admin-photo-strip">${(h.photos?.length?h.photos:[null]).map((_,i)=>`<img src="${imageFor(h,i)}" alt="Шалгах зураг ${i+1}">`).join('')}</div></details>`:`<p class="notice">${ids.map(id=>'№ '+id).join(' · ')}</p>`}<form onsubmit="adminSubmitReview(event)"><input type="hidden" name="ids" value="${ids.join(',')}">${adminSelect('Шийдвэр','status',['approved','pending','rejected','suspended'],ids.length===1?adminReview(h):'approved')}${adminTextarea('Шийдвэрийн тайлбар','reason',ids.length===1?adminState().listingReviews[h.id]?.reason||'':'')}<p class="admin-form-note">Татгалзах, түр зогсоох үед шалтгааныг заавал бичнэ үү.</p><p class="admin-form-error" role="alert"></p>${adminFormActions('Шийдвэр хадгалах')}</form>`);document.querySelector('.modal').classList.add('admin-modal')}
function adminSubmitReview(event){event.preventDefault();const f=new FormData(event.target),ids=String(f.get('ids')).split(',').map(Number),status=String(f.get('status')),reason=String(f.get('reason')||'').trim();if(!ids.length||ids.some(id=>!homes.some(h=>h.id===id))||!['approved','pending','rejected','suspended'].includes(status))return;if(['rejected','suspended'].includes(status)&&!reason)return adminFormError(event,'Шийдвэрийн шалтгааныг оруулна уу.');const before=ids.map(id=>adminReview(homes.find(h=>h.id===id))).join(', ');adminCommit('Зарын хяналт',ids.join(', '),()=>ids.forEach(id=>adminState().listingReviews[id]={status,reason,version:homes.find(h=>h.id===id).updatedAt||'',date:new Date().toISOString()}),before,ADMIN_LABELS[status],reason)}
function adminBrokers(){return brokerAdminPage()+officeAdminPanel()}
function adminOpenBroker(){brokerOpenReview()}
function adminSubmitBroker(event){brokerSubmitDecision(event)}
function adminMemberRows(){return [...(flowState.profile.demo?[{id:'member-local',name:flowState.profile.name,source:'Энэ браузерын демо бүртгэл'}]:[]),...adminState().members].map(m=>({...m,...adminState().memberMeta[m.id]}))}
function adminMembers(){const all=adminMemberRows().filter(m=>adminMatches(m,m.status||'active')),rows=adminPaginate(all);return `${adminHeading('ХЭРЭГЛЭГЧИЙН БҮРТГЭЛ','Хэрэглэгчид','Демо сесс болон тусгайлан нэмсэн жишээ бүртгэлүүд. PRO-ийн хувийн харилцагчийн жагсаалтыг хэрэглэгч гэж тооцохгүй.')} ${adminToolbar('Нэр, бүртгэлийн дугаар',['active','suspended'])}<div class="admin-panel admin-table-panel"><div class="admin-table-scroll"><table class="admin-table"><thead><tr><th>Хэрэглэгч</th><th>Бүртгэлийн эх сурвалж</th><th>Төлөв</th><th>Тэмдэглэл</th><th></th></tr></thead><tbody>${rows.map(m=>`<tr><td><b>${esc(m.name)}</b><small>${esc(m.id)}</small></td><td>${esc(m.source||'Жишээ бүртгэл')}</td><td>${adminBadge(m.status||'active')}</td><td>${esc(m.reason||'—')}</td><td><button data-member="${esc(m.id)}" onclick="adminOpenMember(this.dataset.member)">Удирдах</button></td></tr>`).join('')}</tbody></table></div>${!all.length?adminEmpty('Бүртгэл хараахан алга','Хэрэглэгчийн демо сесс үүсэхэд энд харагдана.'):''}${adminPagination(all.length)}</div><p class="admin-note">Эндэх төлөв нь локал бүртгэл. Серверийн нэвтрэх эрхийг хаах, бодит хэрэглэгчийн үйлдлийг хориглох хамгаалалт холбогдоогүй.</p>`}
function adminOpenMember(id){const m=adminMemberRows().find(m=>m.id===id);if(!m)return;modal(`<h2>${esc(m.name)}</h2><form onsubmit="adminSubmitMember(event)"><input type="hidden" name="id" value="${esc(id)}">${adminSelect('Бүртгэлийн төлөв','status',['active','suspended'],m.status||'active')}${adminTextarea('Тэмдэглэл','reason',m.reason||'')}<p class="admin-form-error" role="alert"></p>${adminFormActions('Хадгалах')}</form>`);document.querySelector('.modal').classList.add('admin-modal')}
function adminSubmitMember(event){event.preventDefault();const f=new FormData(event.target),id=String(f.get('id')),status=String(f.get('status')),reason=String(f.get('reason')||'').trim();if(!adminMemberRows().some(m=>m.id===id)||!['active','suspended'].includes(status))return;if(status==='suspended'&&!reason)return adminFormError(event,'Шалтгаанаа оруулна уу.');adminCommit('Хэрэглэгчийн төлөв',id,()=>adminState().memberMeta[id]={status,reason},'',ADMIN_LABELS[status],reason)}
function adminAds(){const rows=proState().campaigns.filter(c=>adminMatches(c,adminAdState(c)));return `${adminHeading('ЗУУЧЛАГЧИЙН СУРТАЛЧИЛГАА','Зар сурталчилгаа','PRO-оос ирсэн хүсэлт → админ шийдвэр → хугацаатай онцлох зарын демо.')}<div class="admin-inline-summary">${['pending','active','scheduled','paused','expired'].map(s=>`<button onclick="adminFilter='${s}';render()">${adminBadge(s)}<b>${proState().campaigns.filter(c=>adminAdState(c)===s).length}</b></button>`).join('')}</div>${adminToolbar('Аяны нэр, дүүрэг, бүтээгдэхүүн',['pending','active','scheduled','rejected','paused','expired','draft'])}<div class="admin-panel admin-table-panel"><div class="admin-table-scroll"><table class="admin-table"><thead><tr><th>Аян / Зуучлагч</th><th>Төсөв</th><th>Хугацаа</th><th>Төлөв</th><th>Онцлох зар</th><th></th></tr></thead><tbody>${adminPaginate(rows).map(c=>`<tr><td><b>${esc(c.name)}</b><small>${esc(c.area)} · ${esc(proState().office.name)}</small></td><td class="admin-price">${formatMnt(c.budget)}</td><td>${proDate(c.startDate)}<small>→ ${proDate(c.endDate)}</small></td><td>${adminBadge(adminAdState(c))}</td><td>${(c.listingIds||[]).filter(id=>adminPromotion(homes.find(h=>h.id===id)||{})?.id===c.id).length} / ${(c.listingIds||[]).length}</td><td><button data-campaign="${esc(c.id)}" onclick="adminOpenAd(this.dataset.campaign)">Хүсэлт шалгах</button></td></tr>`).join('')}</tbody></table></div>${!rows.length?adminEmpty('Сурталчилгааны хүсэлт алга','PRO → Зар сурталчилгаа хэсэгт хүсэлт хадгалахад энд ирнэ.'):''}${adminPagination(rows.length)}</div><p class="admin-note">Төсөв нь зуучлагчийн төлөвлөгөө; төлөгдсөн орлого биш. Төлбөр, бодит рекламын сервер болон бусад хэрэглэгчийн төхөөрөмж рүү түгээх үйлчилгээ холбогдоогүй.</p>`}
function adminOpenAd(id){const c=proState().campaigns.find(c=>c.id===id);if(!c)return;modal(`<div class="admin-modal-heading"><span>СУРТАЛЧИЛГААНЫ ХЯНАЛТ</span><h2>${esc(c.name)}</h2><p>${esc(c.area)} · ${formatMnt(c.budget)} · ${proDate(c.startDate)} → ${proDate(c.endDate)}</p></div><div class="admin-ad-listings">${(c.listingIds||[]).map(id=>{const h=homes.find(h=>h.id===id);return `<p>${h?esc(h.name):'Зар устсан'} · № ${id} ${h?adminBadge(adminReview(h)):''}</p>`}).join('')}</div>${c.stage==='requested'?`<form onsubmit="adminSubmitAd(event)"><input name="id" type="hidden" value="${esc(c.id)}">${adminSelect('Шийдвэр','status',['approved','pending','rejected','paused'],c.adminStatus||'pending')}${adminTextarea('Админы тайлбар','reason',c.adminReason||'')}<p class="admin-form-note">Батлагдсан, хугацаа нь эхэлсэн бөгөөд нийтэд харагдах зар л онцлох хэсэгт орно.</p><p class="admin-form-error" role="alert"></p>${adminFormActions('Шийдвэр хадгалах')}</form>`:'<p class="notice">Энэ нь зуучлагчийн ноорог. PRO дээр хүсэлт болгон хадгалсны дараа шийдвэр гаргана.</p>'}`);document.querySelector('.modal').classList.add('admin-modal')}
function adminSubmitAd(event){event.preventDefault();const f=new FormData(event.target),id=String(f.get('id')),status=String(f.get('status')),reason=String(f.get('reason')||'').trim(),c=proState().campaigns.find(c=>c.id===id);if(!c||c.stage!=='requested'||!['approved','pending','rejected','paused'].includes(status))return;if(['rejected','paused'].includes(status)&&!reason)return adminFormError(event,'Шалтгаанаа оруулна уу.');if(status==='approved'&&!brokerEligible(c.brokerId||'broker-local'))return adminFormError(event,'Сурталчилгаа хүссэн байгууллагын хоёр шатны хяналт дуусаагүй байна.');if(status==='approved'&&(!c.startDate||!c.endDate||c.startDate>c.endDate||c.endDate<proToday()||!(c.listingIds||[]).length||(c.listingIds||[]).some(id=>{const h=homes.find(h=>h.id===id);return !h||!isPublicListing(h)||c.area&&h.area!==c.area})))return adminFormError(event,'Хугацаа, дүүрэг болон бүх холбоотой зарын нийтэд харагдах төлөвийг шалгана уу.');adminCommit('Сурталчилгааны шийдвэр',c.name,()=>{c.adminStatus=status;c.adminReason=reason;c.reviewedAt=new Date().toISOString()},adminAdState(c),ADMIN_LABELS[status],reason)}
function adminSupportRequests(){return flowState.requests.filter(r=>!['message','phone'].includes(r.kind))}
function adminTickets(kind){const reports=kind==='reports',source=reports?flowState.reports:adminSupportRequests(),rows=source.filter(r=>adminMatches(r,r.adminStatus||'new'));return `${adminHeading(reports?'МЭДЭЭЛЛИЙН ЧАНАР':'ХЭРЭГЛЭГЧТЭЙ ХАРИЛЦАХ',reports?'Мэдээлсэн зарууд':'Хэрэглэгчийн тусламж',reports?'Мэдээллийг шалгаж, шаардлагатай үед зарыг түр зогсооно.':'Хариулт нь хэрэглэгчийн Миний булан дахь хүсэлтийн түүхэнд харагдана. SMS, имэйл илгээхгүй.')}${adminToolbar('Гарчиг, агуулга, зарын дугаар',['new','progress','resolved',...(reports?['dismissed']:[])])}<div class="admin-ticket-layout"><div class="admin-ticket-list">${adminPaginate(rows).map(r=>`<article class="admin-panel admin-ticket"><div><span>${esc(r.date)}</span>${adminBadge(r.adminStatus||'new')}</div><h2>${esc(r.title)}</h2><p>${esc(r.body)}</p>${r.propertyId?'<small>Зар № '+r.propertyId+'</small>':''}${r.adminReply?'<blockquote>'+esc(r.adminReply)+'</blockquote>':''}<button class="admin-primary" data-ticket="${esc(r.id)}" onclick="adminOpenTicket('${kind}',this.dataset.ticket)">${icon('message')}Шийдвэр / Хариу</button></article>`).join('')||`<div class="admin-panel">${adminEmpty('Хүлээгдэж буй бүртгэл алга','Хэрэглэгчийн сайтаас ирсэн хүсэлтүүд энэ хэсэгт холбогдоно.')}</div>`}${adminPagination(rows.length)}</div><aside class="admin-panel admin-ticket-guide"><span class="admin-eyebrow">АЖЛЫН УРСГАЛ</span><h2>${reports?'Шалгах. Тодруулах. Шийдвэрлэх.':'Нэг хүсэлт. Тодорхой хариу.'}</h2>${['Шинэ бүртгэлийн агуулгыг унших','Төлөвийг шалгаж байна болгож өөрчлөх','Тайлбар, хариуг бичиж хадгалах','Шийдвэрийг хэрэглэгчийн түүхэнд харуулах'].map((s,i)=>`<p><b>${i+1}</b>${s}</p>`).join('')}<small>Шийдвэр бүр үйлдлийн түүхэнд хадгалагдана.</small></aside></div>`}
function adminOpenTicket(kind,id){const r=(kind==='reports'?flowState.reports:adminSupportRequests()).find(r=>r.id===id);if(!r)return;modal(`<div class="admin-modal-heading"><span>${kind==='reports'?'МЭДЭЭЛСЭН ЗАР':'ХЭРЭГЛЭГЧИЙН ХҮСЭЛТ'}</span><h2>${esc(r.title)}</h2><p class="admin-ticket-body">${esc(r.body)}</p></div><form onsubmit="adminSubmitTicket(event,'${kind}')"><input name="id" type="hidden" value="${esc(id)}">${adminSelect('Шийдвэрийн төлөв','status',['new','progress','resolved',...(kind==='reports'?['dismissed']:[])],r.adminStatus||'new')}${adminTextarea('Хэрэглэгчид харагдах хариу','reply',r.adminReply||'')}${kind==='reports'&&homes.some(h=>h.id===r.propertyId)?'<label class="admin-check"><input type="checkbox" name="suspend">Холбоотой зарыг түр зогсоох</label>':''}<p class="admin-form-error" role="alert"></p>${adminFormActions('Хариу хадгалах')}</form>`);document.querySelector('.modal').classList.add('admin-modal')}
function adminSubmitTicket(event,kind){event.preventDefault();const f=new FormData(event.target),r=(kind==='reports'?flowState.reports:adminSupportRequests()).find(r=>r.id===f.get('id')),status=String(f.get('status')),reply=String(f.get('reply')||'').trim();if(!r||!['new','progress','resolved',...(kind==='reports'?['dismissed']:[])].includes(status))return;if((['resolved','dismissed'].includes(status)||f.has('suspend'))&&!reply)return adminFormError(event,'Шийдвэрийн тайлбар, хариуг бичнэ үү.');adminCommit(kind==='reports'?'Мэдээллийн шийдвэр':'Тусламжийн хариу',r.title,()=>{r.adminStatus=status;r.adminReply=reply;r.adminUpdatedAt=new Date().toISOString();if(f.has('suspend')&&kind==='reports'){const h=homes.find(h=>h.id===r.propertyId);if(h)adminState().listingReviews[h.id]={status:'suspended',reason:reply,version:h.updatedAt||'',date:new Date().toISOString()}}},r.adminStatus||'new',ADMIN_LABELS[status],reply)}
function adminHistoryReply(item){return item.adminStatus||item.adminReply?`<div class="admin-customer-reply">${adminBadge(item.adminStatus||'progress')}${item.adminReply?'<b>Өрөө · Админы хариу</b><p>'+esc(item.adminReply)+'</p>':''}</div>`:''}
function adminNotices(){const a=adminState();return [...noticeItems.map((v,i)=>({id:String(i),title:v[0],body:v[1],date:'2026-11-09',status:'published',base:true,...a.noticeOverrides[i]})),...a.notices]}
function adminPublicNotices(id){const all=adminNotices().filter(n=>n.status==='published');if(id!==undefined){const n=all.find(n=>n.id===String(id));return `<div class="wrap support-wrap">${helpHeading('notice')}${n?`<article class="notice-detail"><span class="badge">ӨРӨӨ · МЭДЭЭ</span><h2>${esc(n.title)}</h2><p class="muted">${esc(n.date)}</p>${nhNoticeSource(n)}<p class="listing-user-text">${esc(n.body)}</p></article>`:emptyFlow('Мэдээ олдсонгүй','Нийтэлсэн мэдээний жагсаалтаас сонгоно уу.')}<a href="#/notice">← Жагсаалт руу</a></div>`}const rows=all.filter(n=>n.title.toLowerCase().includes(supportQuery.toLowerCase()));return `<div class="wrap support-wrap">${helpHeading('notice')}${supportSearch()}<table class="table notice-table"><thead><tr><th>№</th><th>Гарчиг</th><th>Огноо</th></tr></thead><tbody>${rows.map((n,i)=>`<tr><td>${i+1}</td><td><a href="#/notice/${esc(n.id)}">${esc(n.title)}</a></td><td>${esc(n.date)}</td></tr>`).join('')}</tbody></table>${!rows.length?emptyFlow('Мэдээ алга','Өөр түлхүүр үг оруулна уу.'):''}</div>`}
function adminContent(){const notices=adminContentTab==='notices',all=(notices?adminNotices():flowState.posts.map(p=>({...p,status:p.adminStatus||'published'}))).filter(n=>adminMatches(n,n.status));return `${adminHeading('КОНТЕНТ БА МЭДЭЭЛЭЛ','Мэдээ ба нийтлэл','Мэдээг нийтлэх, архивлах болон хэрэглэгчийн локал нийтлэлийг удирдах.',notices?'<button class="admin-primary" onclick="adminOpenNotice()">'+icon('plus')+'Мэдээ нэмэх</button>':'')}<div class="admin-content-tabs"><button ${notices?'class="active"':''} onclick="adminContentTab='notices';adminResetView();render()">Мэдээ, зарлал</button><button ${!notices?'class="active"':''} onclick="adminContentTab='posts';adminResetView();render()">Хорооллын нийтлэл</button><a href="#/notice">Хэрэглэгчийн харагдац ${icon('arrow-up-right')}</a></div>${adminToolbar('Гарчиг, агуулга',notices?['published','draft','archived']:['published','hidden'])}<div class="admin-panel admin-table-panel"><div class="admin-table-scroll"><table class="admin-table"><thead><tr><th>Гарчиг</th><th>Огноо</th><th>Төлөв</th><th></th></tr></thead><tbody>${adminPaginate(all).map(n=>`<tr><td><b>${esc(n.title)}</b>${!notices&&n.province?'<small>'+esc(nhScopeLabel(n))+'</small>':''}<small>${esc(n.body.slice(0,80))}</small></td><td>${esc(n.date||'—')}</td><td>${adminBadge(n.status)}</td><td><button data-record="${esc(n.id)}" onclick="${notices?'adminOpenNotice(this.dataset.record)':'adminTogglePost(this.dataset.record)'}">${notices?'Засах':n.status==='hidden'?'Дахин нийтлэх':'Нуух'}</button></td></tr>`).join('')}</tbody></table></div>${!all.length?adminEmpty('Контент олдсонгүй','Хайлт, төлөвөө өөрчилнө үү.'):''}${adminPagination(all.length)}</div>`}
function adminOpenNotice(id){const n=adminNotices().find(n=>n.id===id)||{};modal(`<h2>${id?'Мэдээ засах':'Мэдээ нэмэх'}</h2><form onsubmit="adminSubmitNotice(event)"><input name="id" type="hidden" value="${esc(id||'')}"><label class="admin-field">Гарчиг<input name="title" required maxlength="160" value="${esc(n.title||'')}"></label>${adminTextarea('Агуулга','body',n.body||'')}${nhNoticeFields(n)}${adminSelect('Нийтлэх төлөв','status',['draft','published','archived'],n.status||'draft')}<p class="admin-form-error" role="alert"></p>${adminFormActions('Мэдээ хадгалах')}</form>`);document.querySelector('.modal').classList.add('admin-modal')}
function adminSubmitNotice(event){event.preventDefault();const f=new FormData(event.target),id=String(f.get('id')||''),old=adminNotices().find(n=>n.id===id),title=String(f.get('title')||'').trim(),body=String(f.get('body')||'').trim(),status=String(f.get('status'));if(!title||!body)return adminFormError(event,'Гарчиг болон агуулгаа оруулна уу.');if(!['draft','published','archived'].includes(status)||id&&!old)return;const meta=nhNoticeMeta(f,old||{});if(!meta)return adminFormError(event,'Байршил эсвэл эх сурвалжийн холбоосыг шалгана уу.');const item={id:id||flowId(),title,body,status,...meta,date:old?.date||proToday()};adminCommit('Мэдээний өөрчлөлт',title,()=>{if(old?.base)adminState().noticeOverrides[id]=item;else{const i=adminState().notices.findIndex(n=>n.id===id);if(i>=0)adminState().notices[i]={...adminState().notices[i],...item};else adminState().notices.unshift(item)}},old?.status,ADMIN_LABELS[status])}
function adminTogglePost(id){const p=flowState.posts.find(p=>p.id===id);if(!p)return;const next=p.adminStatus==='hidden'?'published':'hidden';adminCommit('Хорооллын нийтлэл',p.title,()=>p.adminStatus=next,p.adminStatus||'published',ADMIN_LABELS[next])}
function adminAnalytics(){const p=proState(),campaigns=p.campaigns,publicCount=homes.filter(isPublicListing).length;return `${adminHeading('ПЛАТФОРМЫН ТАЙЛАН','Тайлан','Одоогийн браузерын бүртгэл. Улс даяарх хэрэглэгч, серверийн үзэлт эсвэл орлогын тайлан биш.',`<button onclick="adminExportAudit()">${icon('download')}Үйлдлийн CSV</button>`)}<div class="admin-metrics">${adminMetric('Нийтэд харагдах зар',publicCount,'apartment',homes.length+' нийт бүртгэл','listings')}${adminMetric('Демо хэрэглэгч',adminMemberRows().length,'users','PRO харилцагчдыг оруулаагүй','members')}${adminMetric('Онцлох зар',adminPromotedHomes().length,'megaphone','Хугацаатай, баталсан сурталчилгаа','ads')}${adminMetric('Хадгалсан шийдвэр',adminState().audit.length,'book-open','Админы локал түүх','audit')}</div><div class="admin-dashboard-grid"><section class="admin-panel"><div class="admin-panel-head"><h2>Дүүрэг дэх зарууд</h2><span>Нийтэд харагдах</span></div><div class="admin-bars">${[...new Set(homes.map(h=>h.area))].map(area=>{const count=homes.filter(h=>h.area===area&&isPublicListing(h)).length,max=Math.max(1,...areas.map(a=>homes.filter(h=>h.area===a&&isPublicListing(h)).length));return `<div><span>${esc(area)}</span><i><b style="width:${count/max*100}%"></b></i><strong>${count}</strong></div>`}).join('')}</div></section><section class="admin-panel"><div class="admin-panel-head"><h2>Сурталчилгааны бүртгэл</h2></div><div class="admin-large-number">${formatMnt(campaigns.filter(c=>c.stage==='requested').reduce((sum,c)=>sum+Number(c.budget||0),0))}</div><p class="admin-note">Ирүүлсэн хүсэлтүүдийн нийт төлөвлөсөн төсөв. Төлөгдсөн орлого биш.</p>${['pending','active','paused','expired','rejected'].map(s=>`<div class="admin-report-line">${adminBadge(s)}<b>${campaigns.filter(c=>adminAdState(c)===s).length}</b></div>`).join('')}</section></div>`}
function adminSettings(){const a=adminState();return `${adminHeading('ҮЙЛЧИЛГЭЭНИЙ ДҮРЭМ','Үйлчилгээний тохиргоо','Шинэ бүртгэлд үйлчлэх нийтлэх дүрэм болон демо ажлын орчны мэдээлэл.')}<section class="admin-panel admin-settings-panel"><div class="admin-panel-head"><div><h2>Зар нийтлэх хяналт</h2><p>Өмнө хадгалсан заруудыг автоматаар өөрчлөхгүй.</p></div>${icon('shield')}</div><form onsubmit="adminSaveSettings(event)"><label class="admin-setting-toggle"><div><b>Бүх шинэ зарыг шалгаж нийтлэх</b><p>Хэрэглэгч эсвэл PRO шинэ/зассан зар админ батлах хүртэл хүлээнэ.</p></div><input type="checkbox" name="reviewListings" ${a.settings.reviewListings?'checked':''}></label><label class="admin-setting-toggle"><div><b>PRO зарыг заавал шалгах</b><p>Байгууллага баталгаажсан байсан ч зуучлагчийн шинэ болон зассан зар бүрийг шалгана. Энэ хамгаалалтыг унтраахгүй.</p></div><input type="checkbox" name="reviewBrokerListings" checked disabled></label>${adminFormActions('Дүрэм хадгалах',false)}</form></section><section class="admin-panel admin-access-note"><h2>Үйл ажиллагааны гурван орчин</h2><div>${[['Хэрэглэгчийн сайт','Зар хайх, хадгалах, лавлагаа илгээх','#/'],['Өрөө PRO','Өөрийн зар, хувийн харилцагч, ажлын хуваарь','#/pro'],['Өрөө ADMIN','Платформын зар, хүсэлт, контентийн шийдвэр','#/admin']].map(([title,copy,url])=>`<a href="${url}"><b>${title}</b><p>${copy}</p>${icon('arrow-up-right')}</a>`).join('')}</div><p class="admin-note">Энэ нь хамгаалагдсан үйлдвэрлэлийн админ систем биш. Серверийн нэвтрэлт, олон шатны баталгаажуулалт, эрхийн шалгалт, байгууллагын тусгаарлалт болон өөрчлөх боломжгүй серверийн аудит хэрэгтэй. Демо админы холбоосыг мэдсэнээр энэ браузерын удирдлагыг нээж болно.</p></section><section class="admin-panel"><div class="admin-panel-head"><div><h2>Жишээ ажлын урсгал</h2><p>Хянах зар, сурталчилгааны хүсэлт, мэдээлэл ба тусламжийн жишээ.</p></div></div><div class="admin-example-actions"><button onclick="adminSeedExamples()">${icon('sparkles')}Жишээ нэмэх</button><button onclick="adminConfirmRemoveExamples()">${icon('trash')}Зөвхөн админы жишээг цэвэрлэх</button></div></section>`}
function adminSaveSettings(event){event.preventDefault();const f=new FormData(event.target),settings={reviewListings:f.has('reviewListings'),reviewBrokerListings:true};adminCommit('Нийтлэх дүрэм','Шинэ болон зассан зар',()=>Object.assign(adminState().settings,settings),JSON.stringify(adminState().settings),JSON.stringify(settings))}
function adminAudit(){const rows=adminState().audit.filter(r=>adminMatches(r,'all'));return `${adminHeading('ҮЙЛ АЖИЛЛАГААНЫ ТҮҮХ','Үйлдлийн түүх','Шийдвэр, шалтгаан, өмнөх/дараах утга. Энэ браузерт хадгална; серверийн хамгаалагдсан аудит биш.',`<button onclick="adminExportAudit()">${icon('download')}CSV татах</button>`)}${adminToolbar('Үйлдэл, бүртгэл, тайлбар')}<div class="admin-panel admin-table-panel"><div class="admin-table-scroll"><table class="admin-table"><thead><tr><th>Огноо / Хэн</th><th>Үйлдэл / Бүртгэл</th><th>Өмнөх → Дараах</th><th>Шалтгаан</th></tr></thead><tbody>${adminPaginate(rows).map(r=>`<tr><td>${esc(r.date.slice(0,10))}<small>${esc(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Ulaanbaatar',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(r.date)))} · ${esc(r.actor)}</small></td><td><b>${esc(r.action)}</b><small>${esc(r.target)}</small></td><td>${esc(ADMIN_LABELS[r.before]||r.before)} → ${esc(ADMIN_LABELS[r.after]||r.after)}</td><td>${esc(r.reason||'—')}</td></tr>`).join('')}</tbody></table></div>${!rows.length?adminEmpty('Үйлдлийн түүх алга','Хадгалсан шийдвэр бүр энэ жагсаалтад орно.'):''}${adminPagination(rows.length)}</div>`}
function adminExportAudit(){const fields=['date','actor','action','target','before','after','reason'],csv='\uFEFF'+[['Огноо','Админ','Үйлдэл','Бүртгэл','Өмнөх','Дараах','Тайлбар'],...adminState().audit.map(r=>fields.map(f=>r[f]))].map(row=>row.map(proCsvValue).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='oroo-admin-audit-'+proToday()+'.csv';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function adminSelect(label,name,options,value){return `<label class="admin-field">${label}<select name="${name}" aria-label="${esc(label)}" required>${options.map(s=>`<option value="${s}" ${value===s?'selected':''}>${ADMIN_LABELS[s]}</option>`).join('')}</select></label>`}
function adminTextarea(label,name,value){return `<label class="admin-field">${label}<textarea name="${name}" aria-label="${esc(label)}" rows="4" maxlength="4000">${esc(value)}</textarea></label>`}
function adminFormActions(label,cancel=true){return `<div class="admin-form-actions">${cancel?'<button type="button" onclick="closeOverlay()">Буцах</button>':''}<button class="admin-primary" type="submit">${icon('check')}${label}</button></div>`}
function adminFormError(event,text){event.target.querySelector('.admin-form-error').textContent=text}
function adminSeedExamples(){const a=adminState();if(a.examplesLoaded){toast('Жишээ ажлын урсгал аль хэдийн байна');return}const id=Date.now()+700,first=homes.find(h=>!h.local),today=proToday(),end=new Date(today+'T12:00:00Z');end.setUTCDate(end.getUTCDate()+30);if(!first)return;const h={...first,id,name:'Жишээ · Хянах орон сууц',desc:'Жишээ бүртгэл · Админаар хянах зар',local:true,proManaged:true,contactRole:'agent',agencyName:proState().office.name,contactName:'Жишээ зуучлагч',moderationStatus:'pending',listingStatus:'published',photos:[],sampleOrigin:'admin',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};const ok=adminCommit('Жишээ нэмсэн','Админы ажлын урсгал',()=>{a.examplesLoaded=true;flowState.listings.push(h);proState().campaigns.push({id:flowId(),name:'Жишээ · Онцлох зарын хүсэлт',kind:'premium',area:h.area,listingIds:[id],budget:500000,startDate:today,endDate:end.toISOString().slice(0,10),stage:'requested',adminStatus:'pending',sampleOrigin:'admin'});flowState.reports.push({id:flowId(),propertyId:first.id,title:'Жишээ · Зураг тодруулах хүсэлт',body:'Зарын зургийн мэдээллийг шалгаж өгнө үү. Энэ нь зөвхөн жишээ.',date:today,sampleOrigin:'admin'});flowState.requests.push({id:flowId(),kind:'support',title:'Жишээ · Хайлтын тусламж',body:'Байршлаар хэрхэн хайх вэ? Жишээ үйлчилгээний хүсэлт.',date:today,sampleOrigin:'admin'});a.members.push({id:flowId(),name:'Жишээ · Тэмүүлэн',source:'Админы ажлын урсгалын жишээ',sampleOrigin:'admin'});a.notices.push({id:flowId(),title:'Жишээ · Өрөө үйлчилгээний мэдээлэл',body:'Мэдээг нийтлэх болон архивлах ажлын урсгалын жишээ.',date:today,status:'draft',sampleOrigin:'admin'})},'','Жишээ мэдээлэл');if(ok){homes.push(h);render()}}
function adminConfirmRemoveExamples(){modal('<h2>Админы жишээг цэвэрлэх үү?</h2><p>Зөвхөн “Жишээ” гэж тэмдэглэсэн админы ажлын урсгалаар нэмсэн зар, сурталчилгаа, мэдээлэл, хүсэлт, хэрэглэгч, мэдээг хасна. Бусад бүртгэлийг хэвээр хадгална.</p><div class="admin-form-actions"><button onclick="closeOverlay()">Буцах</button><button class="admin-primary" onclick="adminRemoveExamples()">Жишээ цэвэрлэх</button></div>');document.querySelector('.modal').classList.add('admin-modal')}
function adminRemoveExamples(){const ids=new Set(flowState.listings.filter(h=>h.sampleOrigin==='admin').map(h=>h.id));const ok=adminCommit('Жишээ цэвэрлэсэн','Админы ажлын урсгал',()=>{for(const key of ['listings','reports','requests'])flowState[key]=flowState[key].filter(r=>r.sampleOrigin!=='admin');proState().campaigns=proState().campaigns.filter(c=>c.sampleOrigin!=='admin');adminState().members=adminState().members.filter(m=>m.sampleOrigin!=='admin');adminState().notices=adminState().notices.filter(n=>n.sampleOrigin!=='admin');for(const id of ids)delete adminState().listingReviews[id];adminState().examplesLoaded=false});if(ok){for(let i=homes.length-1;i>=0;i--)if(ids.has(homes[i].id))homes.splice(i,1);render()}}

function adminListingPolicyNote(d){return adminState().settings.reviewListings||!!adminBrokerId(d)?'<p class="notice">'+icon('shield')+' Энэ зар админы хяналтад орно. Баталсны дараа хэрэглэгчийн хайлтад харагдана.</p>':''}
